  1→//! Configuration validation rules.
  2→//!
  3→//! This module validates configuration for correctness:
  4→//! - Steps must have either template or command
  5→//! - depends_on must reference existing steps
  6→//! - Workflows must reference existing steps
  7→//! - No circular dependencies allowed
  8→
  9→use crate::config::schema::BivvyConfig;
 10→use crate::error::{BivvyError, Result};
 11→use std::collections::HashSet;
 12→
 13→/// Validation error with context.
 14→#[derive(Debug, Clone)]
 15→pub struct ValidationError {
 16→    /// Rule identifier
 17→    pub rule: String,
 18→    /// Human-readable error message
 19→    pub message: String,
 20→    /// Step name if error is step-specific
 21→    pub step: Option<String>,
 22→    /// Workflow name if error is workflow-specific
 23→    pub workflow: Option<String>,
 24→}
 25→
 26→/// Validate a configuration and return all errors.
 27→///
 28→/// This function collects all validation errors rather than stopping
 29→/// at the first one, allowing users to fix multiple issues at once.
 30→pub fn validate_config(config: &BivvyConfig) -> Vec<ValidationError> {
 31→    let mut errors = Vec::new();
 32→
 33→    errors.extend(validate_steps(config));
 34→    errors.extend(validate_workflows(config));
 35→    errors.extend(validate_dependencies(config));
 36→
 37→    errors
 38→}
 39→
 40→/// Validate step definitions.
 41→fn validate_steps(config: &BivvyConfig) -> Vec<ValidationError> {
 42→    let mut errors = Vec::new();
 43→
 44→    for (name, step) in &config.steps {
 45→        // Step must have either template or command
 46→        if step.template.is_none() && step.command.is_none() {
 47→            errors.push(ValidationError {
 48→                rule: "missing-command".to_string(),
 49→                message: format!("Step '{}' must have either 'template' or 'command'", name),
 50→                step: Some(name.clone()),
 51→                workflow: None,
 52→            });
 53→        }
 54→
 55→        // Validate depends_on references
 56→        for dep in &step.depends_on {
 57→            if !config.steps.contains_key(dep) {
 58→                errors.push(ValidationError {
 59→                    rule: "unknown-step".to_string(),
 60→                    message: format!("Step '{}' depends on '{}' which does not exist", name, dep),
 61→                    step: Some(name.clone()),
 62→                    workflow: None,
 63→                });
 64→            }
 65→        }
 66→    }
 67→
 68→    errors
 69→}
 70→
 71→/// Validate workflow definitions.
 72→fn validate_workflows(config: &BivvyConfig) -> Vec<ValidationError> {
 73→    let mut errors = Vec::new();
 74→
 75→    for (name, workflow) in &config.workflows {
 76→        // Validate step references
 77→        for step_name in &workflow.steps {
 78→            if !config.steps.contains_key(step_name) {
 79→                errors.push(ValidationError {
 80→                    rule: "unknown-workflow-step".to_string(),
 81→                    message: format!(
 82→                        "Workflow '{}' references step '{}' which does not exist",
 83→                        name, step_name
 84→                    ),
 85→                    step: None,
 86→                    workflow: Some(name.clone()),
 87→                });
 88→            }
 89→        }
 90→
 91→        // Validate override references
 92→        for step_name in workflow.overrides.keys() {
 93→            if !workflow.steps.contains(step_name) {
 94→                errors.push(ValidationError {
 95→                    rule: "unknown-override-step".to_string(),
 96→                    message: format!(
 97→                        "Workflow '{}' has override for '{}' which is not in the workflow",
 98→                        name, step_name
 99→                    ),
100→                    step: None,

  1→//! Variable interpolation for configuration values.
  2→//!
  3→//! Bivvy supports variable interpolation in config values using `${variable}` syntax.
  4→//!
  5→//! # Syntax
  6→//!
  7→//! - `${variable_name}` - replaced with variable value
  8→//! - `$${escaped}` - produces literal `${escaped}` in output
  9→//!
 10→//! # Example
 11→//!
 12→//! ```yaml
 13→//! command: "echo Hello, ${name}!"
 14→//! # With name="World", produces: echo Hello, World!
 15→//! ```
 16→
 17→use crate::error::{BivvyError, Result};
 18→use std::collections::{HashMap, HashSet};
 19→
 20→/// A segment of an interpolated string.
 21→#[derive(Debug, Clone, PartialEq)]
 22→pub enum Segment {
 23→    /// Literal text
 24→    Literal(String),
 25→    /// Variable reference: ${name}
 26→    Variable(String),
 27→}
 28→
 29→/// Parse a string containing ${var} interpolations.
 30→///
 31→/// Supports:
 32→/// - `${variable_name}` - variable interpolation
 33→/// - `$${escaped}` - literal `${escaped}` in output
 34→///
 35→/// # Returns
 36→///
 37→/// Vec of segments representing the parsed string
 38→pub fn parse_interpolation(input: &str) -> Vec<Segment> {
 39→    let mut segments = Vec::new();
 40→    let mut chars = input.chars().peekable();
 41→    let mut current_literal = String::new();
 42→
 43→    while let Some(c) = chars.next() {
 44→        if c == '$' {
 45→            match chars.peek() {
 46→                Some('$') => {
 47→                    // Escaped: $$ becomes $
 48→                    chars.next();
 49→                    if chars.peek() == Some(&'{') {
 50→                        // $${...} -> literal ${...}
 51→                        chars.next(); // consume {
 52→                        current_literal.push('$');
 53→                        current_literal.push('{');
 54→                        // Read until closing brace
 55→                        while let Some(&c) = chars.peek() {
 56→                            chars.next();
 57→                            current_literal.push(c);
 58→                            if c == '}' {
 59→                                break;
 60→                            }
 61→                        }
 62→                    } else {
 63→                        current_literal.push('$');
 64→                    }
 65→                }
 66→                Some('{') => {
 67→                    // Start of variable
 68→                    chars.next(); // consume {
 69→
 70→                    // Flush current literal
 71→                    if !current_literal.is_empty() {
 72→                        segments.push(Segment::Literal(std::mem::take(&mut current_literal)));
 73→                    }
 74→
 75→                    // Read variable name until }
 76→                    let mut var_name = String::new();
 77→                    while let Some(&c) = chars.peek() {
 78→                        if c == '}' {
 79→                            chars.next();
 80→                            break;
 81→                        }
 82→                        var_name.push(chars.next().unwrap());
 83→                    }
 84→
 85→                    segments.push(Segment::Variable(var_name));
 86→                }
 87→                _ => {
 88→                    current_literal.push(c);
 89→                }
 90→            }
 91→        } else {
 92→            current_literal.push(c);
 93→        }
 94→    }
 95→
 96→    // Flush remaining literal
 97→    if !current_literal.is_empty() {
 98→        segments.push(Segment::Literal(current_literal));
 99→    }
100→
101→    segments
102→}
103→
104→/// Extract all variable names from an interpolated string.
105→///
106→/// Returns unique variable names found in the string.
107→pub fn extract_variables(input: &str) -> HashSet<String> {
108→    parse_interpolation(input)
109→        .into_iter()
110→        .filter_map(|seg| match seg {
111→            Segment::Variable(name) => Some(name),
112→            _ => None,
113→        })
114→        .collect()
115→}
116→
117→/// Check if a string contains any interpolation.
118→pub fn has_interpolation(input: &str) -> bool {
119→    parse_interpolation(input)
120→        .iter()
121→        .any(|seg| matches!(seg, Segment::Variable(_)))
122→}
