        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();

        // Project config extends base and overrides install command
        fs::write(
            bivvy_dir.join("config.yml"),
            format!(
                r#"
extends:
  - url: {}
app_name: MyApp
steps:
  install:
    command: yarn install
"#,
                server.url("/base.yml")
